<!DOCTYPE html>
<html lang="id">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Dashboard Admin | Roda Care</title><link rel="stylesheet" href="css/style.css"><script defer src="js/admin.js"></script></head>
<body class="dashboard-page">
  <aside class="sidebar" id="adminSidebar"><a class="brand sidebar-brand" href="admin-dashboard.html"><span class="brand-icon" aria-hidden="true">⚙</span> <span class="brand-name">Roda<span>Care</span></span></a><p class="side-label">MENU ADMIN</p><a class="side-link selected" href="#overview">▦ <span>Dashboard Admin</span></a><a class="side-link" href="#users">♙ <span>Data Pengguna</span></a><a class="side-link" href="#vehicles">🚘 <span>Data Kendaraan</span></a><a class="side-link" href="#services">🔧 <span>Data Servis</span></a><a class="side-link" href="index.html">↗ <span>Halaman Utama</span></a><div class="sidebar-bottom"><div class="avatar">AD</div><div><b>Administrator</b><small>Admin Roda Care</small></div></div></aside>
  <main class="dashboard-main"><header class="dash-topbar"><button class="menu-toggle dash-menu" onclick="document.getElementById('adminSidebar').classList.toggle('open')">☰</button><div><span class="muted">Panel pengelolaan</span><h2>Dashboard Admin</h2></div><button class="btn btn-outline" onclick="adminLogout()">Keluar</button></header>
    <section class="welcome-banner admin-banner" id="overview"><div><span class="eyebrow">PUSAT KENDALI ADMIN</span><h1>Selamat datang, Admin! 👋</h1><p>Pantau data pengguna, kendaraan, dan catatan servis pada aplikasi Roda Care.</p></div><div class="banner-car">🛠️</div></section>
    <section class="stats-grid"><article class="stat-card"><span class="stat-icon blue">♙</span><p>Total Pengguna</p><h3 id="adminUserCount">0</h3><small>Akun terdaftar di browser</small></article><article class="stat-card"><span class="stat-icon orange">🚘</span><p>Total Kendaraan</p><h3 id="adminVehicleCount">0</h3><small>Data kendaraan</small></article><article class="stat-card"><span class="stat-icon green">🔧</span><p>Total Data Servis</p><h3 id="adminServiceCount">0</h3><small>Catatan perawatan</small></article></section>
    <section class="data-section" id="users"><div class="section-title-row"><div><span class="eyebrow">MANAJEMEN AKUN</span><h2>Data Pengguna</h2><p class="muted">Daftar akun yang mendaftar melalui halaman Register.</p></div></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Email</th><th>Tanggal Daftar</th></tr></thead><tbody id="adminUserRows"></tbody></table></div></section>
    <section class="data-section" id="vehicles"><div class="section-title-row"><div><span class="eyebrow">DATA APLIKASI</span><h2>Data Kendaraan</h2><p class="muted">Ringkasan kendaraan yang tersimpan pada browser ini.</p></div></div><div class="table-wrap"><table><thead><tr><th>Nama Kendaraan</th><th>Nomor Polisi</th><th>Jenis</th></tr></thead><tbody id="adminVehicleRows"></tbody></table></div></section>
    <section class="data-section" id="services"><div class="section-title-row"><div><span class="eyebrow">RIWAYAT PERAWATAN</span><h2>Data Servis</h2><p class="muted">Pantau daftar servis dan statusnya.</p></div></div><div class="table-wrap"><table><thead><tr><th>Kendaraan</th><th>Jenis Servis</th><th>Tanggal</th><th>Status</th></tr></thead><tbody id="adminServiceRows"></tbody></table></div></section>
    <footer class="dash-footer">© 2026 Roda Care · Panel admin demo menggunakan localStorage browser.</footer>
  </main>
</body></html>
